 "content": "from collections import deque


def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    seen = set()
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 5 or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < h and 0 <= nx < w and grid[ny][nx] == 5 and (ny, nx) not in seen:
                        seen.add((ny, nx))
                        q.append((ny, nx))
            r0 = min(y for y, x in cells)
            r1 = max(y for y, x in cells)
            c0 = min(x for y, x in cells)
            c1 = max(x for y, x in cells)
            # The objects are three-sided rectangular frames with a one-cell
            # opening in the top edge. Fill the cavity and extend that opening left.
            gaps = [x for x in range(c0, c1 + 1) if grid[r0][x] == 0]
            if r0 > 0 and gaps:
                gap = gaps[0]
                for y in range(r0 + 1, r1):
                    for x in range(c0 + 1, c1):
                        if out[y][x] == 0:
                            out[y][x] = 2
                out[r0][gap] = 2
                for x in range(gap + 1):
                    out[r0 - 1][x] = 2
    return out


